catalog_script_client.script:
function onSubmit() {
    // Type appropriate comment here, and begin script below
    var url = top.location.href;

    if (url.indexOf("number") < 0) {
        return;
    }

    // Requested item id
    var value = url.split("number=");

    // Task id
    var taskid;

    if (url.indexOf("taskid") < 0) {
        taskid = '';
    } else {
        taskid = value[0].split("taskid=")[1].split("&")[0];
    }

    var ga = new GLideAjax("resubmitcatalogitem3");
    ga.addParam("sysparm_name", "resubmitcatalogitemdaction");
    ga.addParam("task_id", taskid);
    ga.addParam("sys_id", value[1]);
    ga.addParam("additional_information", g_form.getValue('additional_information'));
    ga.getXML(setVars);

    function setVars(response) {
        var returnVariables = response.responseXML.documentElement.getAttribute("answer");
        top.window.location.href = top.location.origin + "/sp?id=sc_cat_item&sys_id=3D6c87d828831a6a50cfe0a470ceaad380";
        alert('Your request has been submitted');
	}
    return false;
}
